    */
    @Test @Timeout(60)
    fun test_23_optionsOnCheck_otpReturns200()  {
        
        val token_adam : String = given()
                .contentType("application/json")
                .body(" { " + 
                    " \"email\" : \"adam007@example.com\", " + 
                    " \"password\" : \"adam007!123\" " + 
                    " } ")
                .post("${baseUrlOfSut}/identity/api/auth/login")
                .then().extract().response().path("token")!!
                
        val auth_adam : String = "Bearer " + token_adam
        
        given().accept("*/*")
                .header("Authorization", auth_adam) // adam
                .options("${baseUrlOfSut}/identity/api/auth/v3/check-otp")
                .then()
                .statusCode(200)
                .assertThat()
                // .header("allow", "POST,OPTIONS")
                .body(isEmptyOrNullString())
    }
    
    
